WITH base AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, CONCAT(txn_type, ', ', merchant) AS txn_type_merchant FROM transactions WHERE amount <= 2600), scored AS (SELECT id, txn_type, merchant, is_flagged, txn_type_merchant, MAX(amount) OVER w_running AS last7_max_amount, SUM(amount) OVER w_running AS last7_sum_amount, AVG(amount) OVER w_running AS last7_avg_amount FROM base WINDOW w_running AS (PARTITION BY merchant, txn_type ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), ranked AS (SELECT id, merchant, txn_type_merchant FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY last7_max_amount DESC, id) AS rn FROM scored) x WHERE rn = 1), cleaned AS (SELECT *, COALESCE(merchant, 'unassigned') AS merchant_filled, COALESCE(merchant, 'OTHER') AS merchant_filled_2 FROM ranked WHERE merchant IS NOT NULL AND merchant NOT IN ('Grab', 'Starbucks')), base_transactions AS (SELECT id, merchant, txn_type_merchant, LOWER(merchant) AS merchant_lower FROM cleaned WHERE merchant IS DISTINCT FROM 'Starbucks'), cleaned_transactions AS (SELECT *, TRIM(merchant) AS clean_merchant FROM base_transactions WHERE merchant IN ('Starbucks', 'Shell')), valid AS (SELECT id, merchant, txn_type_merchant, merchant_lower, clean_merchant, TRIM(merchant) AS clean_merchant_2 FROM cleaned_transactions WHERE merchant IN ('Starbucks', 'Lazada', 'Amazon')) SELECT id, merchant, txn_type_merchant, merchant_lower, clean_merchant, clean_merchant_2, CASE WHEN merchant RLIKE '^(Lazada|Amazon)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS merchant_zone FROM valid ORDER BY merchant_zone;
